nextflow_process {

    name "Test Process SAVANA_RUN"
    script "../main.nf"
    process "SAVANA_RUN"

    tag "modules"
    tag "modules_nfcore"
    tag "savana"
    tag "savana/run"

    test("homo_sapiens - nanopore - chr1 - empty output") {

        when {
            process {
                """
                def contig_list = file('contigs.txt')
                contig_list.text = "chr1"
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test2.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test2.sorted.bam.bai', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test.sorted.phased.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test.sorted.phased.bam.bai', checkIfExists: true)
                ]

                input[1] = [
                    [ id:'ref' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ]

                input[2] = [
                    [ id:'contigs' ],
                    [contig_list]
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.sv_breakpoints_vcf.get(0).get(1)).vcf.summary.contains('variantCount=0') }, // VCF summary has no variants
                { assert file(process.out.sv_breakpoints_bedpe.get(0).get(1)).size() == 0 }, // BEDPE file is empty
                { assert file(process.out.sv_breakpoints_read_support.get(0).get(1)).readLines().size() == 1 }, // read support file has only header line
                { assert file(process.out.inserted_sequences.get(0).get(1)).size() == 0 }, // inserted sequences file is empty
                { assert snapshot(process.out.findAll { key, val -> key.startsWith('versions') }).match() }
            )
        }
    }

    test("homo_sapiens - nanopore - no contig") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test2.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test2.sorted.bam.bai', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test.sorted.phased.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test.sorted.phased.bam.bai', checkIfExists: true)
                ]

                input[1] = [
                    [ id:'ref' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ]

                input[2] = [
                    [ id:'contigs' ],
                    []
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    path(process.out.sv_breakpoints_vcf.get(0).get(1)).vcf.summary,
                    file(process.out.sv_breakpoints_bedpe.get(0).get(1)).name,
                    file(process.out.sv_breakpoints_read_support.get(0).get(1)).readLines().size(),
                    file(process.out.inserted_sequences.get(0).get(1)).name,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("homo_sapiens - nanopore - stub") {

        options "-stub"

        when {
            process {
                """
                def contig_list = file('contigs.txt')
                contig_list.text = "chr22"
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test2.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test2.sorted.bam.bai', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test.sorted.phased.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test.sorted.phased.bam.bai', checkIfExists: true)
                ]

                input[1] = [
                    [ id:'ref' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ]

                input[2] = [
                    [ id:'contigs' ],
                    [contig_list]
                ]
                """
            }
        }

        then {
            assert process.success
            assert snapshot(sanitizeOutput(process.out)).match()
        }
    }
}

